using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class Lights123SolidFix{static double next;static Lights123SolidFix(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+4;if(File.Exists("D:/-11-scene3-audit/lights123-fixed.txt")||!File.Exists("D:/-11-scene3-audit/lights123-normals-ready.txt")||EditorApplication.isUpdating||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.name!="scene3")return;try{var rs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>new[]{"light1","light2","light3"}.Contains(r.name)).ToArray();if(rs.Length!=3)throw new Exception("Expected three lamp renderers, found "+rs.Length);var shader=Shader.Find("BlenderScene3/PrincipledTransfer");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Opaque crystal shader is not ready");EditorSceneManager.SaveScene(s);File.Copy(s.path,"D:/-11-scene3-audit/scene3.before-solid-lights123.unity",true);var report=new List<string>();foreach(var r in rs){var src=r.sharedMaterial;var path="Assets/BlenderScene3/Materials/"+r.name+"SolidCrystal.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(src);AssetDatabase.CreateAsset(mat,path);}else mat.CopyPropertiesFromMaterial(src);mat.shader=shader;mat.renderQueue=2000;mat.SetOverrideTag("RenderType","Opaque");mat.SetColor("_Color",new Color(.7941471f,.39584476f,1,1).gamma);mat.SetColor("_EmissionColor",Color.black);mat.SetFloat("_Metallic",0);mat.SetTexture("_AlphaTex",null);mat.DisableKeyword("_ALPHABLEND_ON");mat.DisableKeyword("_ALPHAPREMULTIPLY_ON");var normalPath="Assets/BlenderScene3/"+r.name+"CrystalNormal.png";var imp=AssetImporter.GetAtPath(normalPath) as TextureImporter;if(imp==null)throw new Exception("Normal map not imported: "+r.name);imp.textureType=TextureImporterType.NormalMap;imp.sRGBTexture=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(normalPath));mat.SetFloat("_UseNormal",1);mat.SetFloat("_NormalStrength",1);mat.SetVector("_NormalUV",new Vector4(1,1,0,0));var channels=mat.GetVector("_UVChannels");channels.w=channels.z;mat.SetVector("_UVChannels",channels);var angles=mat.GetVector("_Angles");angles.w=0;mat.SetVector("_Angles",angles);EditorUtility.SetDirty(mat);Undo.RecordObject(r,"Restore solid crystal lamp appearance");r.sharedMaterials=r.sharedMaterials.Select(x=>mat).ToArray();r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.TwoSided;r.reflectionProbeUsage=UnityEngine.Rendering.ReflectionProbeUsage.BlendProbes;PrefabUtility.RecordPrefabInstancePropertyModifications(r);report.Add(r.name+"|shader="+r.sharedMaterial.shader.name+"|queue="+mat.renderQueue+"|alpha="+mat.GetColor("_Color").a+"|normal="+normalPath+"|roughnessMap="+AssetDatabase.GetAssetPath(mat.GetTexture("_RoughTex")));}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllLines("D:/-11-scene3-audit/lights123-fixed.txt",report);SceneView.RepaintAll();}catch(Exception e){File.WriteAllText("D:/-11-scene3-audit/lights123-fix-error.txt",e.ToString());}}}
